/* Changing one axis re-derives the others: equipment may carry its own default
   execution, and attachment has to be re-scoped because a dumbbell takes none. */
export function withAxis(leaf, axis, value) {
  const m = movementById(leaf.movement);
  const next = Object.assign({}, leaf, { [axis]: value });
  if (!m) return next;
  if (axis === 'equipment') {
    const ed = m.executionDefaults && m.executionDefaults[value];
    if (ed && (m.execution || []).includes(ed)) next.execution = ed;
    if (!(m.execution || []).includes(next.execution)) next.execution = m.defaultExecution;
  }
  const allowed = attachmentsFor(m, next.equipment);
  next.attachment = !allowed.length ? 'none'
    : (allowed.includes(next.attachment) ? next.attachment
      : (allowed.includes(m.defaultAttachment) ? m.defaultAttachment : allowed[0]));
  return next;
}

/* The pill on an exercise card. Each half opens the picker on its own tab. */
export function leafChip(leaf, ei) {
  const m = movementById(leaf.movement);
  const atts = m ? attachmentsFor(m, leaf.equipment) : [];
  return `<div class="leafchip">
    <button data-axis="${ei}.equipment">${EQ_ICON[leaf.equipment] || ''}${esc(EQ_TITLE[leaf.equipment] || leaf.equipment)}</button>
    <button data-axis="${ei}.execution">${esc(EXEC_LABEL[leaf.execution] || leaf.execution)}</button>
    ${atts.length > 1 ? `<button data-axis="${ei}.attachment">${esc(ATT_TITLE[leaf.attachment] || leaf.attachment)}</button>` : ''}
  </div>`;
}


/* The identity of an entry, for every history/PR join. */
/* An isometric entry gets its own key, so a 20 s loaded hold and a set of ten
   never contend for the same record or share a history. Computed, never
   persisted. */
/* A time cap is its own pool too: 20 reps in a minute and a set of 20 aren't
   the same lift (B1). And so is a lift with chains, bands, a slingshot or
   equipped (D10): prKey's "#chains" part comes before the "|" suffixes. */
export function exKey(e) { return e && e.leaf ? prKey(e.leaf, e.mods) + (e.iso === true ? '|iso' : '') + (e.cap > 0 ? '|cap' + e.cap : '') : ''; }
export function exName(e) { return e && e.leaf ? displayName(e.leaf) : (e && e.legacyName) || ''; }
/* A set counts as working when it is not a warm-up. */
export function isWorking(s) { return s.setType !== 'warmup'; }
export function isWarm(s) { return s.setType === 'warmup'; }
/* Set roles (roadmap B3; setType, r&d/specs/exercise-system-phase1.md §5.3).
   warmup: no volume, no PR. working / top / backoff / amrap: volume and PR —
   top and back-off are how a session is laid out, not a different kind of
   effort. drop: volume, never a PR or an e1RM (it's done tired), and it hangs
   off the set above it as one chain. */
export function isDrop(s) { return s.setType === 'drop'; }
export function isPRSet(s) { return isWorking(s) && !isDrop(s); }
export const SET_ROLES = [
  ['warmup', 'Warm-up', 'W', 'Not counted in volume or PRs'],
  ['working', 'Working', '', 'A normal set'],
  ['top', 'Top set', 'T', 'The heaviest set of the day'],
  ['backoff', 'Back-off', 'B', 'Lighter sets after the top set'],
  ['amrap', 'AMRAP', 'A', 'As many reps as possible'],
  ['drop', 'Drop set', '↳', 'Straight on from the set above, lighter · volume only, never a PR'],
];
function roleOf(s) { return SET_ROLES.find(r => r[0] === (s.setType || 'working')) || SET_ROLES[1]; }
/* Set numbers skip warm-ups and drops: a drop chain reads as one set. */
export function setNumber(sets, si) {
  const s = sets[si];
  if (isWarm(s)) return 'W';
  if (isDrop(s) && si > 0) return '↳';
  return String(sets.slice(0, si + 1).filter((x, i) => !isWarm(x) && !(isDrop(x) && i > 0)).length);
}
/* The set-number box: its role letter and number, and the tap target for the
   role picker. */
export function setNoBtn(sets, si, attr) {
  const s = sets[si], r = roleOf(s), n = setNumber(sets, si);
  const txt = isWarm(s) || (isDrop(s) && si > 0) ? n : `${r[2]}${n}`;
  const fl = feelWords(s);
  return `<button class="setno role-${r[0]}${hasFeel(s) ? ' flagged' : ''}" ${attr} title="Set role: ${r[1]}${fl ? ' · ' + fl : ''}" aria-label="Set ${esc(n)}, ${r[1]}${fl ? `, flagged ${fl.replace(/[⚠〰]\s?/g, '')}` : ''}. Change role or flag">${txt}</button>`;
}
/* ---------------- pain and fatigue (roadmap C5) ----------------
   A quick flag, on a set or on the whole session: pain, fatigue, and a note.
   It annotates and nothing more — PRs, volume and progression ignore it, so
   flagging an honest bad day never costs a record. Stored as `feel`. */
export function hasFeel(x) { return !!(x && x.feel && (x.feel.pain || x.feel.fatigue || x.feel.note)); }
export function feelWords(x) {
  if (!hasFeel(x)) return '';
  return [x.feel.pain ? '⚠ pain' : '', x.feel.fatigue ? '〰 fatigue' : ''].filter(Boolean).join(' · ');
}
export function feelSuffix(x) {
  if (!hasFeel(x)) return '';
  const w = feelWords(x);
  return ` <span class="feeltag">${esc(w || '✎')}${x.feel.note ? ` — ${esc(x.feel.note)}` : ''}</span>`;
}
export function feelChips(x) {
  if (!hasFeel(x)) return '';
  return `${x.feel.pain ? ' <span class="chip feel">⚠ PAIN</span>' : ''}${x.feel.fatigue ? ' <span class="chip feel">〰 FATIGUE</span>' : ''}`;
}
/* The two toggles and a note, as a block for a sheet. Writes to obj.feel. */
export function feelBlock(obj, prefix) {
  const f = obj.feel || {};
  return `<div class="eyebrow" style="margin:12px 0 6px">How it felt</div>
    <div class="row" style="gap:8px">
      <button class="btn sm grow ${f.pain ? 'primary' : 'ghost'}" data-feel="${prefix}.pain" aria-pressed="${f.pain ? 'true' : 'false'}">⚠ Pain</button>
      <button class="btn sm grow ${f.fatigue ? 'primary' : 'ghost'}" data-feel="${prefix}.fatigue" aria-pressed="${f.fatigue ? 'true' : 'false'}">〰 Fatigue</button>
    </div>
    <input data-feelnote="${prefix}" value="${esc(f.note || '')}" placeholder="Where, how bad — optional" maxlength="120" aria-label="Note on how it felt" style="margin-top:8px">`;
}
/* A set's label in lists: "Set 2", "W", or "↳" for a drop hanging off the set above. */
/* An entry-shaped object from a PR key, so exTag can name "in 1 min" or "hold". */
export function keyEntry(k) {
  const parts = String(k).split('|');
  const e = { leaf: keyLeaf(k), mods: keyPR(k), sets: [] };
  parts.slice(1).forEach(p => { if (p === 'iso') e.iso = true; else if (p.startsWith('cap')) e.cap = +p.slice(3); });
  return e;
}
export function setListLabel(sets, si) { const n = setNumber(sets, si); return Number.isFinite(+n) ? 'Set ' + n : n; }
export function roleSuffix(s) { const w = roleWord(s); return w ? ` <span class="dimmer">· ${w}</span>` : ''; }
/* Short role word for set lists: "top", "back-off", "AMRAP", "drop". */
export function roleWord(s) { const t = s.setType; return t === 'top' ? 'top' : t === 'backoff' ? 'back-off' : t === 'amrap' ? 'AMRAP' : t === 'drop' ? 'drop' : ''; }

/* ============================================================
   EXERCISE DEMOS — r&d/specs/exercise-demo-spec.md
   A side-view outline mannequin drawn in inline SVG: capsule segments posed
   by forward kinematics from keyframes per movement pattern, with a couple of
   named solvers (bar over midfoot, two-link IK). Patterns are data; the
   engine draws them all. Nothing here is stored except Your notes
   (S.exNotes, synced).
   ============================================================ */
const DEMO_L = { shin: 0.44, thigh: 0.43, torso: 0.52, upper: 0.30, fore: 0.30, headR: 0.105, ankleY: 0.09, heel: -0.07, toe: 0.19 };
const DEMO_W = { shin: 0.11, thigh: 0.16, torso: 0.25, upper: 0.095, fore: 0.08, foot: 0.075 };
const DEMO_MID = 0.045;   // midfoot, metres in front of the ankle — what "over midfoot" aims at
const DEMO_PLATE = 0.225; // a 20 kg plate's radius: also the bar's height off the floor

const dP = (x, y) => ({ x, y });
const dAdd = (a, b) => dP(a.x + b.x, a.y + b.y);
const dSub = (a, b) => dP(a.x - b.x, a.y - b.y);
const dMul = (a, k) => dP(a.x * k, a.y * k);
const dLen = a => Math.hypot(a.x, a.y);
const dLerp = (a, b, t) => dP(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t);
const dNum = (a, b, t) => a + (b - a) * t;
/* an angle from vertical, forward (the way the lifter faces) positive */
const dDir = deg => dP(Math.sin(deg * Math.PI / 180), Math.cos(deg * Math.PI / 180));
/* the side of a segment a→b that faces forward when it hangs down */
const dAnt = (a, b) => { const d = dSub(b, a), l = dLen(d) || 1; return dP(-d.y / l, d.x / l); };

/* Two-link IK: elbow (or knee) between root and target. bend picks which of
   the two solutions — 'down', 'up', 'fwd' or 'back' — so the pattern says
   which way the joint points instead of knowing the maths. */
function demoIK(root, target, L1, L2, bend) {
  let d = dSub(target, root), dist = dLen(d) || 1e-6;
  const reach = L1 + L2 - 1e-4, min = Math.abs(L1 - L2) + 1e-4;
  if (dist > reach) { target = dAdd(root, dMul(d, reach / dist)); d = dSub(target, root); dist = reach; }
  if (dist < min) { target = dAdd(root, dMul(d, min / dist)); d = dSub(target, root); dist = min; }
  const base = Math.atan2(d.y, d.x);
  const a = Math.acos(Math.max(-1, Math.min(1, (L1 * L1 + dist * dist - L2 * L2) / (2 * L1 * dist))));
  const c1 = dAdd(root, dP(L1 * Math.cos(base + a), L1 * Math.sin(base + a)));
  const c2 = dAdd(root, dP(L1 * Math.cos(base - a), L1 * Math.sin(base - a)));
  const pick = { down: c => -c.y, up: c => c.y, fwd: c => c.x, back: c => -c.x }[bend || 'down'];
  return { mid: pick(c1) >= pick(c2) ? c1 : c2, end: target };
}

/* Easing between keyframes, and a keyframe value at p (0 = start, 1 = far end).
   A keyframe is [start, end] or [[p, v], [p, v], …] for a curve with stops. */
const dEase = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
function dKF(k, p) {
  if (k == null) return 0;
  if (typeof k === 'number') return k;
  if (typeof k[0] === 'number') return dNum(k[0], k[1], p);
  for (let i = 1; i < k.length; i++) if (p <= k[i][0]) {
    const [p0, v0] = k[i - 1], [p1, v1] = k[i];
    return dNum(v0, v1, p1 > p0 ? (p - p0) / (p1 - p0) : 1);
  }
  return k[k.length - 1][1];
}

const dRad = a => a * Math.PI / 180;
/* angle from vertical-down, forward positive (arms, hanging legs) */
const dDown = deg => dP(Math.sin(dRad(deg)), -Math.cos(dRad(deg)));
const dUnit = a => { const l = dLen(a) || 1; return dP(a.x / l, a.y / l); };

/* ---------- where the load sits, per hold ----------
   Every hold returns the bar (or bell) point from the torso, so the torso
   solver can put it over midfoot. u = torso direction (hip → shoulder),
   f = the way the chest faces. */
const DEMO_HOLDS = {
  back:   (sh, u, f) => dAdd(dAdd(sh, dMul(f, -0.085)), dMul(u, -0.02)),      // high on the traps
  front:  (sh, u, f) => dAdd(dAdd(sh, dMul(f, 0.105)), dMul(u, -0.035)),      // on the front delts
  goblet: (sh, u, f) => dAdd(dAdd(sh, dMul(f, 0.17)), dMul(u, -0.16)),        // against the chest
  hands:  (sh, u) => dAdd(dAdd(sh, dMul(u, -0.04)), dP(-0.02, -(DEMO_L.upper + DEMO_L.fore))),  // straight arms, shoulders just ahead of the bar
};
function demoTorso(hip, a, hold) {
  const u = dDir(a), f = dP(u.y, -u.x), sh = dAdd(hip, dMul(u, DEMO_L.torso));
  return { u, f, sh, bar: DEMO_HOLDS[hold] ? DEMO_HOLDS[hold](sh, u, f) : null };
}
/* bar over midfoot: the bar moves forward as the torso leans, so bisection
   finds the one lean that puts it there */
function demoSolveTorso(hip, hold, target) {
  let lo = -20, hi = 89;
  for (let i = 0; i < 40; i++) { const mid = (lo + hi) / 2; if (demoTorso(hip, mid, hold).bar.x < target) lo = mid; else hi = mid; }
  return (lo + hi) / 2;
}
const demoFootFlat = ankle => [dAdd(ankle, dP(DEMO_L.heel + 0.035, -0.05)), dAdd(ankle, dP(DEMO_L.toe - 0.035, -0.055))];
/* a foot that isn't on the floor follows its shin */
function demoFootAlong(knee, ankle) {
  const s = dUnit(dSub(ankle, knee)), fw = dP(-s.y, s.x);
  return [dAdd(dAdd(ankle, dMul(s, 0.05)), dMul(fw, -0.035)), dAdd(dAdd(ankle, dMul(s, 0.055)), dMul(fw, 0.155))];
}

/* Hand and hip targets: [anchor, a, b], or stops [[p, anchor, a, b], …].
   root = the shoulder joint (+dx, +dy); world = absolute; chest = a point a
   of the way from hip to shoulder, b out from the chest; mid = over midfoot
   (+dx), b above the shoulder joint. */
function demoAnchor(B, s) {
  const [k, a, b] = s;
  if (k === 'root') return dAdd(B.root, dP(a, b));
  if (k === 'chest') return dAdd(dLerp(B.hip, B.sh, a), dMul(B.f, DEMO_W.torso / 2 + b));
  if (k === 'mid') return dP(DEMO_MID + a, B.root.y + b);
  return dP(a, b);
}
function demoTarget(B, kf, p) {
  if (typeof kf[0][0] === 'string') return dLerp(demoAnchor(B, kf[0]), demoAnchor(B, kf[1]), p);
  for (let i = 1; i < kf.length; i++) if (p <= kf[i][0]) {
    const a = kf[i - 1], b = kf[i];
    return dLerp(demoAnchor(B, a.slice(1)), demoAnchor(B, b.slice(1)), b[0] > a[0] ? (p - a[0]) / (b[0] - a[0]) : 1);
  }
  return demoAnchor(B, kf[kf.length - 1].slice(1));
}

/* ---------- bases ----------
   Each base turns keyframes at p into the body below the arms: joints, leg
   and foot segments, the torso frame, and any bench, seat or bar it rests
   on. g(key) reads a value: movement override → equipment → pattern. */
const DEMO_BASES = {
  /* forward kinematics from a fixed ankle — shin, thigh, then torso */
  stand(g, p) {
    /* heel: degrees the heel lifts, pivoting on the toes (calf raise, sissy
       squat). The ankle rises with it and the legs build up from there.
       Negative: the toes lift instead, pivoting on the heel (tibialis raise). */
    const L = DEMO_L, lift = dRad(dKF(g('heel') || 0, p));
    const toe = dP(L.toe - 0.035, 0.035), heel = dP(L.heel + 0.035, 0.04), piv = lift < 0 ? heel : toe;
    const rot = v => dP(v.x * Math.cos(lift) + v.y * Math.sin(lift), -v.x * Math.sin(lift) + v.y * Math.cos(lift));
    const turn = q => dAdd(piv, rot(dSub(q, piv)));
    const ankle = lift ? turn(dP(0, L.ankleY)) : dP(0, L.ankleY);
    const foot = lift > 0 ? [turn(heel), toe] : lift < 0 ? [heel, turn(toe)] : demoFootFlat(ankle);
    const knee = dAdd(ankle, dMul(dDir(dKF(g('shin'), p)), L.shin));
    const th = dRad(dKF(g('thigh'), p));
    const hip = dAdd(knee, dMul(dP(-Math.sin(th), Math.cos(th)), L.thigh));
    const hold = g('hold');
    const a = g('solve') === 'midfoot' && DEMO_HOLDS[hold] ? demoSolveTorso(hip, hold, DEMO_MID + (g('barX') || 0)) : dKF(g('torso'), p);
    const T = demoTorso(hip, a, hold);
    return { ...T, hip, segs: { foot: [...foot, DEMO_W.foot], shin: [knee, ankle, DEMO_W.shin], thigh: [hip, knee, DEMO_W.thigh] } };
  },
  /* split stance: both feet planted, the hip follows its keyframes, each leg
     solved by IK. The back leg is drawn first, behind the front one. */
  split(g, p) {
    const L = DEMO_L;
    const fa = dP(g('frontX') ?? 0.3, L.ankleY), ra = dP(...(g('rear') || [-0.56, 0.12])), rt = dP(...(g('rearToe') || [-0.39, 0.02]));
    const hip = demoTarget({}, g('hipKF'), p);
    const front = demoIK(hip, fa, L.thigh, L.shin, 'fwd'), rear = demoIK(hip, ra, L.thigh, L.shin, 'down');
    const T = demoTorso(hip, dKF(g('torso'), p), g('hold'));
    return { ...T, hip, segs: {
      foot2: [ra, rt, DEMO_W.foot * 0.9], shin2: [rear.mid, rear.end, DEMO_W.shin], thigh2: [hip, rear.mid, DEMO_W.thigh],
      foot: [...demoFootFlat(fa), DEMO_W.foot], shin: [front.mid, front.end, DEMO_W.shin], thigh: [hip, front.mid, DEMO_W.thigh],
    }, kit: g('rearBench') ? [`<rect x="${ra.x - 0.3}" y="0" width="0.42" height="${ra.y - 0.05}" class="dm-pad"/>`] : [] };
  },
  /* sitting: hip fixed on a seat; thigh angle above horizontal, shin angle
     from vertical. Feet flat on the floor unless they're up on a footplate. */
  seat(g, p) {
    const L = DEMO_L, hip = dP(0, 0.52);
    const ta = dRad(g('thighA') ?? 0), knee = dAdd(hip, dMul(dP(Math.cos(ta), Math.sin(ta)), L.thigh));
    const ankle = dAdd(knee, dMul(dDown(g('shinA') ?? 4), L.shin));
    const T = demoTorso(hip, dKF(g('torso'), p), g('hold'));
    const kit = [`<rect x="-0.2" y="0" width="0.34" height="${hip.y - 0.075}" class="dm-pad"/>`];
    if (g('kneePad')) kit.push(`<rect x="${knee.x - 0.08}" y="${knee.y + 0.07}" width="0.16" height="0.07" class="dm-pad"/>`);
    if (g('backPad')) { const b0 = dAdd(hip, dMul(T.f, -0.16)), b1 = dAdd(T.sh, dMul(T.f, -0.16)); kit.push(demoLine(b0, b1, 0.07, 'stroke:var(--line)'), demoLine(b0, dP(b0.x, 0), 0.025, 'stroke:var(--dm-kit)')); }
    if (g('footPlate')) kit.push(demoLine(dP(ankle.x + 0.06, 0), dP(ankle.x + 0.12, ankle.y + 0.2), 0.04, 'stroke:var(--dm-kit)'));
    return { ...T, hip, kit, segs: { foot: [...(g('footPlate') ? demoFootAlong(knee, ankle) : demoFootFlat(ankle)), DEMO_W.foot], shin: [knee, ankle, DEMO_W.shin], thigh: [hip, knee, DEMO_W.thigh] } };
  },
  /* lying on a bench, head to the left. incline tilts the back pad up. */
  bench(g, p) {
    const L = DEMO_L, inc = dRad(g('incline') || 0), hip = dP(0.2, 0.56);
    const u = dP(-Math.cos(inc), Math.sin(inc)), f = dP(u.y, -u.x), sh = dAdd(hip, dMul(u, L.torso));
    let knee, ankle, foot;
    if (g('legsUp')) {
      knee = dAdd(hip, dMul(dP(Math.cos(dRad(55)), Math.sin(dRad(55))), L.thigh));
      ankle = dAdd(knee, dMul(dP(Math.cos(dRad(-15)), Math.sin(dRad(-15))), L.shin));
      foot = demoFootAlong(knee, ankle);
    } else {
      knee = dAdd(hip, dMul(dP(Math.cos(dRad(-20)), Math.sin(dRad(-20))), L.thigh));
      const dy = knee.y - L.ankleY;
      ankle = dP(knee.x - Math.sqrt(Math.max(0, L.shin * L.shin - dy * dy)), L.ankleY);
      foot = demoFootFlat(ankle);
    }
    const pad0 = dAdd(hip, dMul(f, -(DEMO_W.torso / 2 + 0.035))), pad1 = dAdd(dAdd(sh, dMul(u, 0.06)), dMul(f, -(DEMO_W.torso / 2 + 0.035)));
    const kit = [demoLine(dAdd(pad0, dMul(u, -0.12)), pad1, 0.07, 'stroke:var(--line)'),
      demoLine(dP(pad0.x - 0.02, pad0.y - 0.04), dP(pad0.x - 0.02, 0), 0.03, 'stroke:var(--dm-kit)'),
      demoLine(dP(pad1.x + 0.05, pad1.y - 0.04), dP(pad1.x + 0.05, 0), 0.03, 'stroke:var(--dm-kit)')];
    return { u, f, sh, hip, bar: null, kit, segs: { foot: [...foot, DEMO_W.foot], shin: [knee, ankle, DEMO_W.shin], thigh: [hip, knee, DEMO_W.thigh] } };
  },
  /* hanging from a bar: the hands are fixed and the body is pulled up to
     them — the shoulder follows a target, the rest hangs off it */
  hang(g, p) {
    const L = DEMO_L, H = dP(0, 2.15);
    const root = dAdd(H, dLerp(dP(...g('rootFrom')), dP(...g('rootTo')), p));
    const a = dKF(g('torso'), p), u = dDir(a), f = dP(u.y, -u.x);
    const sh = dAdd(root, dMul(u, 0.04)), hip = dSub(sh, dMul(u, L.torso));
    const knee = dAdd(hip, dMul(dDown(18), L.thigh)), ankle = dAdd(knee, dMul(dDown(-45), L.shin));
    const kit = [`<line x1="-0.25" y1="${H.y}" x2="0.25" y2="${H.y}" class="dm-rail"/>`];
    return { u, f, sh, hip, root, bar: H, kit, armsTo: H, segs: { foot: [...demoFootAlong(knee, ankle), DEMO_W.foot], shin: [knee, ankle, DEMO_W.shin], thigh: [hip, knee, DEMO_W.thigh] } };
  },
  /* facing the viewer — both sides drawn, arms move out to the sides */
  front(g, p) {
    const segs = {}, hipY = 0.93, shY = 1.42;
    const ab = dKF(g('abduct'), p), bend = g('elbowBend') || 12;
    [-1, 1].forEach((s, i) => {
      const n = i ? '2' : '', hp = dP(0.085 * s, hipY), kn = dP(0.095 * s, 0.51), an = dP(0.1 * s, DEMO_L.ankleY);
      segs['thigh' + n] = [hp, kn, DEMO_W.thigh]; segs['shin' + n] = [kn, an, DEMO_W.shin];
      segs['foot' + n] = [dP(0.08 * s, 0.04), dP(0.15 * s, 0.04), DEMO_W.foot];
      const root = dP(0.17 * s, shY - 0.04);
      const el = dAdd(root, dMul(dP(Math.sin(dRad(ab)) * s, -Math.cos(dRad(ab))), DEMO_L.upper));
      const hd = dAdd(el, dMul(dP(Math.sin(dRad(ab + bend)) * s, -Math.cos(dRad(ab + bend))), DEMO_L.fore - 0.03));
      segs['upper' + n] = [root, el, DEMO_W.upper]; segs['fore' + n] = [el, hd, DEMO_W.fore];
    });
    segs.torso = [dP(0, hipY + 0.03), dP(0, shY), 0.3];
    return { front: true, u: dP(0, 1), f: dP(0, 0), sh: dP(0, shY), hip: dP(0, hipY), segs, hands: [segs.fore[1], segs.fore2[1]] };
  },
};

/* ---------- arms ----------
   'hold': hands go to the load's hold point (IK). 'target': hands follow
   keyframed targets (IK). 'angles': upper arm and forearm angles from the
   vertical, in world space — so a curl's upper arm stays still. */
function demoArms(B, g, p) {
  const L = DEMO_L, root = B.root || dAdd(B.sh, dMul(B.u, -0.04));
  B.root = root;
  if (B.armsTo) { const k = demoIK(root, B.armsTo, L.upper, L.fore, g('elbow') || 'fwd'); return { root, elbow: k.mid, hand: k.end }; }
  const mode = g('arms');
  if ((mode === 'hold' && B.bar) || mode === 'target') {
    const tgt = mode === 'hold' ? B.bar : demoTarget(B, g('hand'), p);
    const k = demoIK(root, tgt, L.upper, L.fore, g('elbow') || 'down');
    return { root, elbow: k.mid, hand: k.end };
  }
  const elbow = dAdd(root, dMul(dDown(dKF(g('upperArm') || 0, p)), L.upper));
  return { root, elbow, hand: dAdd(elbow, dMul(dDown(dKF(g('foreArm') || 0, p)), L.fore)) };
}

