function demoFor(m) {
  const map = m && DEMO_MAP[m.id];
  const pat = map && DEMO_PATTERNS[map.pattern];
  return pat ? { pat, o: map.o || {}, name: map.pattern } : null;
}

/* The whole pose at p for one equipment choice. */
function demoPose(d, eqKey, p) {
  const { pat, o } = d;
  const pe = Object.assign({}, pat.eq._, pat.eq[eqKey] || {});
  const oe = Object.assign({}, (o.eq || {})._, (o.eq || {})[eqKey] || {});
  const g = k => oe[k] !== undefined ? oe[k] : o[k] !== undefined ? o[k] : pe[k] !== undefined ? pe[k] : pat[k];
  const B = DEMO_BASES[g('base')](g, p);
  const L = DEMO_L, segs = Object.assign({}, B.segs), kit = (B.kit || []).slice();
  let hand = null, hands = [];
  if (B.front) hands = B.hands;
  else {
    const A = demoArms(B, g, p);
    segs.torso = [B.hip, B.sh, DEMO_W.torso, -1];
    segs.upper = [A.root, A.elbow, DEMO_W.upper];
    segs.fore = [A.elbow, A.hand, DEMO_W.fore];
    hand = A.hand; hands = [hand];
  }
  /* the head carries on from the torso, held a little more upright when
     standing or sitting; lying and hanging it just follows the spine */
  const upright = !B.front && (g('base') === 'stand' || g('base') === 'seat' || g('base') === 'split');
  const hd = upright ? dUnit(dAdd(B.u, dP(0, 1.4))) : B.u;
  const head = dAdd(dAdd(B.sh, dMul(B.u, 0.02)), dMul(hd, L.headR + 0.06));
  const draw = g('draw') || 'none';
  const holdBar = (g('arms') === 'hold' && B.bar) || (g('hold') === 'goblet' && B.bar);
  const load = draw === 'none' || draw === 'belt' ? null : holdBar ? B.bar : hand;
  /* kit that depends on the pose */
  if (g('box')) kit.push(`<rect x="${B.hip.x - 0.3}" y="0" width="0.36" height="${g('box')}" class="dm-pad"/>`);
  if (g('pins') && typeof g('pins') === 'number') kit.push(`<line x1="${DEMO_MID - 0.12}" y1="${g('pins') - 0.04}" x2="${DEMO_MID + 0.12}" y2="${g('pins') - 0.04}" class="dm-rail"/>`);
  if (g('pins') === true) { const lo = demoTarget(B, g('hand'), 0); kit.push(`<line x1="${lo.x - 0.1}" y1="${lo.y - 0.04}" x2="${lo.x + 0.1}" y2="${lo.y - 0.04}" class="dm-rail"/>`); }
  if (g('preacher')) { const a = dAdd(segs.upper[0], dMul(dAnt(segs.upper[0], segs.upper[1]), -0.07)), b = dAdd(segs.upper[1], dMul(dAnt(segs.upper[0], segs.upper[1]), -0.07)); kit.push(demoLine(dLerp(a, b, 0.1), dLerp(a, b, 1.05), 0.06, 'stroke:var(--line)'), demoLine(dLerp(a, b, 0.6), dP(dLerp(a, b, 0.6).x - 0.05, 0), 0.03, 'stroke:var(--dm-kit)')); }
  /* a pad behind the back (hack squat sled); the seat base draws its own */
  if (g('backPad') && g('base') !== 'seat') { const a = dAdd(dLerp(B.hip, B.sh, 0.0), dMul(B.f, -(DEMO_W.torso / 2 + 0.05))), b = dAdd(dLerp(B.hip, B.sh, 1.05), dMul(B.f, -(DEMO_W.torso / 2 + 0.05))); kit.push(demoLine(a, b, 0.08, 'stroke:var(--line)'), demoLine(dAdd(a, dMul(dSub(a, b), 0.3)), dAdd(b, dMul(dSub(b, a), 0.25)), 0.02, 'stroke:var(--dm-kit)')); }
  if (g('chestPad')) { const a = dAdd(dLerp(B.hip, B.sh, 0.25), dMul(B.f, DEMO_W.torso / 2 + 0.06)), b = dAdd(dLerp(B.hip, B.sh, 0.95), dMul(B.f, DEMO_W.torso / 2 + 0.06)); kit.push(demoLine(a, b, 0.07, 'stroke:var(--line)'), demoLine(a, dP(a.x, 0), 0.03, 'stroke:var(--dm-kit)')); }
  return { segs, head, hand, hands, bar: load, kit, g, B, draw };
}

/* ---------- drawing ---------- */
function demoLine(a, b, w, style) {
  return `<line x1="${a.x.toFixed(4)}" y1="${a.y.toFixed(4)}" x2="${b.x.toFixed(4)}" y2="${b.y.toFixed(4)}" stroke-width="${w.toFixed(4)}" style="${style}" stroke-linecap="round"/>`;
}
const demoPlate = (c, r) => `<circle cx="${c.x}" cy="${c.y}" r="${r}" class="dm-plate"/><circle cx="${c.x}" cy="${c.y}" r="${r - 0.035}" class="dm-rim"/><circle cx="${c.x}" cy="${c.y}" r="0.055" class="dm-rim"/>`;
/* behind: kit, rails, cables, plates (a plate in front hides the head and
   the silhouette stops reading as a person). front: the bar and bells. */
function demoEquip(P, layer) {
  const g = P.g, c = P.bar, out = [];
  if (layer === 'back') {
    out.push(...P.kit);
    if (g('rail') && c) out.push(`<line x1="${c.x}" y1="0" x2="${c.x}" y2="2.1" class="dm-rail"/>`);
    if (P.draw === 'belt') { const h = P.B.hip; out.push(`<line x1="${h.x}" y1="${h.y}" x2="${h.x + 0.02}" y2="0.3" class="dm-cable"/><rect x="${h.x - 0.1}" y="0.1" width="0.22" height="0.2" class="dm-plate"/>`); }
    if ((P.draw === 'cable' || P.draw === 'band') && P.hands.length) {
      P.hands.forEach((h, i) => {
        let an = g('anchor');
        if (an === 'above') an = [h.x, 2.3];
        else if (an === 'across') an = [-h.x * 1.6, 0.12];
        out.push(`<line x1="${h.x}" y1="${h.y}" x2="${an[0]}" y2="${an[1]}" class="${P.draw === 'band' ? 'dm-band' : 'dm-cable'}"/>`);
        if (P.draw === 'cable' && !i) out.push(`<circle cx="${an[0]}" cy="${an[1]}" r="0.035" class="dm-plate"/>`);
      });
    }
    if ((P.draw === 'barbell' || P.draw === 'trap') && c) out.push(demoPlate(c, g('plateR') || DEMO_PLATE));
    if (P.draw === 'log' && c) out.push(`<circle cx="${c.x}" cy="${c.y}" r="0.16" class="dm-plate"/>`);
    return out.join('');
  }
  if ((P.draw === 'barbell' || P.draw === 'trap' || P.draw === 'log') && c) {
    if (g('ssb')) out.push(demoLine(c, dAdd(c, dP(0.2, -0.12)), 0.03, 'stroke:var(--dm-ink)'));
    out.push(`<circle cx="${c.x}" cy="${c.y}" r="0.032" class="dm-bar"/>`);
  }
  const bells = g('hold') === 'goblet' && c ? [c] : P.hands;
  bells.forEach(h => {
    if (P.draw === 'dumbbell') out.push(`<circle cx="${h.x}" cy="${h.y}" r="0.07" class="dm-plate"/><circle cx="${h.x}" cy="${h.y}" r="0.022" class="dm-bar"/>`);
    if (P.draw === 'kettlebell') out.push(`<circle cx="${h.x}" cy="${h.y - 0.08}" r="0.09" class="dm-plate"/><path d="M${h.x - 0.04} ${h.y - 0.02} Q${h.x} ${h.y + 0.05} ${h.x + 0.04} ${h.y - 0.02}" class="dm-cable"/>`);
    if (P.draw === 'plate') out.push(`<circle cx="${h.x}" cy="${h.y}" r="0.12" class="dm-plate"/>`);
    if (P.draw === 'cable') out.push(`<circle cx="${h.x}" cy="${h.y}" r="0.022" class="dm-bar"/>`);
  });
  return out.join('');
}

function demoSVG(d, eqKey, p, e, opts, m, trail) {
  const P = demoPose(d, eqKey, p);
  /* Two layers, each drawn as one silhouette (every outline, then every
     fill): the body, then the near arm on top — otherwise an arm across the
     torso merges into it and disappears. */
  const layers = P.B.front ? [['foot2', 'shin2', 'thigh2', 'upper2', 'fore2', 'foot', 'shin', 'thigh', 'torso', 'upper', 'fore', 'head']]
    : [['foot2', 'shin2', 'thigh2', 'foot', 'shin', 'thigh', 'torso', 'head'], ['upper', 'fore']];
  const sil = keys => {
    const o = [], f = [];
    keys.forEach(k => {
      if (k === 'head') { o.push(`<circle cx="${P.head.x}" cy="${P.head.y}" r="${DEMO_L.headR + 0.013}" style="fill:var(--dm-ink)"/>`); f.push(`<circle cx="${P.head.x}" cy="${P.head.y}" r="${DEMO_L.headR}" style="fill:var(--dm-body)"/>`); return; }
      if (!P.segs[k]) return;
      const [a, b, w] = P.segs[k];
      o.push(demoLine(a, b, w + 0.026, 'stroke:var(--dm-ink)')); f.push(demoLine(a, b, w, 'stroke:var(--dm-body)'));
    });
    return o.join('') + f.join('');
  };
  const mus = {};
  if (opts.muscles) {
    const col = `stroke:color-mix(in srgb, var(--red) ${Math.round(e * 100)}%, var(--gold));opacity:${(0.35 + 0.6 * e).toFixed(2)}`;
    const seen = new Set(), front = P.B.front;
    (m.primary || []).forEach(name => (DEMO_MUSCLES[name] || []).forEach(([seg, a0, a1, side]) => {
      (front ? [seg, seg + '2'] : [seg]).forEach(k => {
        const key = `${k}${a0}${a1}${side}`; if (seen.has(key)) return; seen.add(key);
        const s = P.segs[k]; if (!s) return;
        const [a, b, w, flip] = s, sd = front ? 0 : side;
        const off = dMul(dMul(dAnt(a, b), flip || 1), sd * w * 0.22);
        (mus[k] = mus[k] || []).push(demoLine(dAdd(dLerp(a, b, a0), off), dAdd(dLerp(a, b, a1), off), w * (sd ? 0.46 : 0.55), col));
      });
    }));
  }
  const path = [];
  if (opts.path) {
    if (P.g('path') === 'midfoot') path.push(`<line x1="${DEMO_MID}" y1="0" x2="${DEMO_MID}" y2="2.2" class="dm-mid"/>`);
    for (let i = 1; i < trail.length; i++) {
      const a = trail[i - 1], b = trail[i];
      path.push(`<line x1="${a.x.toFixed(4)}" y1="${a.y.toFixed(4)}" x2="${b.x.toFixed(4)}" y2="${b.y.toFixed(4)}" class="dm-trail" style="stroke-opacity:${(i / trail.length * 0.9).toFixed(2)}"/>`);
    }
  }
  return `${demoEquip(P, 'back')}${path.join('')}${layers.map(keys => `<g>${sil(keys)}</g><g>${keys.map(k => (mus[k] || []).join('')).join('')}</g>`).join('')}${demoEquip(P, 'front')}`;
}

/* The view box: the whole rep, padded, square, so the lifter doesn't jump
   about while it plays. */
function demoBox(d, eqKey) {
  let x0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (let i = 0; i <= 10; i++) {
    const P = demoPose(d, eqKey, i / 10);
    const pts = [P.head, ...P.hands, ...Object.values(P.segs).flatMap(s => [s[0], s[1]])];
    pts.forEach(q => { x0 = Math.min(x0, q.x); x1 = Math.max(x1, q.x); y1 = Math.max(y1, q.y); });
    if (P.bar && /barbell|trap/.test(P.draw)) { const r = P.g('plateR') || DEMO_PLATE; x0 = Math.min(x0, P.bar.x - r); x1 = Math.max(x1, P.bar.x + r); y1 = Math.max(y1, P.bar.y + r); }
    y1 = Math.max(y1, P.head.y + DEMO_L.headR);
    if (P.B.armsTo) y1 = Math.max(y1, P.B.armsTo.y + 0.05);
  }
  const pad = 0.1, aspect = 1;
  let w = (x1 - x0) + pad * 2, h = y1 + pad + 0.06;
  if (w / h < aspect) w = h * aspect; else h = w / aspect;
  const cx = (x0 + x1) / 2;
  return { x: cx - w / 2, y: -h + 0.06, w, h };
}

/* ---------- timeline ----------
   hold at the start (brace) → go → pause at the far end → back. The
   eccentric takes ~1.8 s and the concentric ~1.2 s, whichever way round. */
function demoTimeline(pat) {
  const goC = pat.concentric === 'go';
  const parts = [
    { k: 'hold', end: 0, dur: 0.5 },
    { k: goC ? 'con' : 'ecc', from: 0, to: 1, dur: goC ? 1.2 : 1.8 },
    { k: 'hold', end: 1, dur: 0.35 },
    { k: goC ? 'ecc' : 'con', from: 1, to: 0, dur: goC ? 1.8 : 1.2 },
  ];
  return { parts, total: parts.reduce((s, x) => s + x.dur, 0), hardEnd: goC ? 0 : 1 };
}
function demoAt(tl, t) {
  t = ((t % tl.total) + tl.total) % tl.total;
  let i = 0;
  for (; i < tl.parts.length - 1 && t >= tl.parts[i].dur; i++) t -= tl.parts[i].dur;
  const part = tl.parts[i], x = Math.min(1, t / part.dur);
  const hard = q => tl.hardEnd === 1 ? q : 1 - q;
  if (part.k === 'hold') return { p: part.end, phase: i, e: part.end === tl.hardEnd ? 0.72 : 0.12 };
  const p = dNum(part.from, part.to, dEase(x));
  if (part.k === 'ecc') return { p, phase: i, e: 0.18 + 0.5 * hard(p) };
  /* concentric: effort peaks a third of the way out of the hole (the
     sticking region), then falls off toward lockout */
  const e = x < 0.35 ? 0.72 + 0.28 * (x / 0.35) : 1 - 0.85 * ((x - 0.35) / 0.65);
  return { p, phase: i, e };
}

/* ---------- the widget ---------- */
const DEMO_OPTS = { playing: true, slow: false, muscles: true, path: true };
let _demoRun = null;   // the live loop, so a redraw can stop the old one

/* skip: true on an equipment means that variant is a different lift the
   pattern can't show (barbell hack squat) — no figure beats a wrong one */
const demoSkip = (d, eq) => !!demoPose(d, eq, 0).g('skip');
export function demoBlock(m, leaf) {
  const d = demoFor(m);
  if (!d || demoSkip(d, (leaf && leaf.equipment) || m.defaultEquipment)) return '';
  return `<div class="dm" id="dmWrap">
    <svg class="dm-svg" id="dmSvg" role="img" aria-label="Animated figure showing a ${esc(m.name.toLowerCase())}, ${(d.o.base || d.pat.base) === 'front' ? 'front' : 'side'} view" preserveAspectRatio="xMidYMid meet"></svg>
    <div class="dm-phase" id="dmPhase" aria-hidden="true">${esc((d.o.labels || d.pat.labels)[0])}</div>
    <div class="dm-ctl">
      <button class="btn xs" id="dmPlay" aria-label="${DEMO_OPTS.playing ? 'Pause' : 'Play'}">${DEMO_OPTS.playing ? '❚❚' : '▶'}</button>
      <button class="btn xs ${DEMO_OPTS.slow ? 'on' : ''}" id="dmSlow" aria-pressed="${DEMO_OPTS.slow}">Slow</button>
      <button class="btn xs ${DEMO_OPTS.muscles ? 'on' : ''}" id="dmMus" aria-pressed="${DEMO_OPTS.muscles}">Muscles</button>
      <button class="btn xs ${DEMO_OPTS.path ? 'on' : ''}" id="dmPath" aria-pressed="${DEMO_OPTS.path}">Bar path</button>
    </div>
    <label class="dm-scrub"><span>Depth</span><input type="range" id="dmScrub" min="0" max="1000" value="0" aria-label="Scrub through the rep"></label>
  </div>`;
}

export function demoMount(bg, m, leaf) {
  if (_demoRun) { _demoRun.stop(); _demoRun = null; }
  const svg = $('#dmSvg', bg);
  const d = demoFor(m);
  if (!svg || !d) return;
  const eqKey = (leaf && leaf.equipment) || m.defaultEquipment;
  const tl = demoTimeline({ concentric: d.o.concentric || d.pat.concentric });
  const box = demoBox(d, eqKey);
  svg.setAttribute('viewBox', `${box.x.toFixed(3)} ${box.y.toFixed(3)} ${box.w.toFixed(3)} ${box.h.toFixed(3)}`);
  const phaseEl = $('#dmPhase', bg), scrub = $('#dmScrub', bg);
  let reduce = false;
  try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* old browser: animate */ }
  let t = 0, last = null, raf = 0, scrubP = null, trail = [];
  if (reduce && DEMO_OPTS.playing) { DEMO_OPTS.playing = false; scrubP = 0.5; }
  const ground = `<line x1="${box.x}" y1="0" x2="${box.x + box.w}" y2="0" class="dm-ground"/>`;
  const draw = (st) => {
    if (DEMO_OPTS.path) {
      const P = demoPose(d, eqKey, st.p);
      const b = P.bar || P.hand;
      if (b) { trail.push(dP(b.x, b.y)); if (trail.length > 70) trail.shift(); }
    }
    svg.innerHTML = `<g transform="scale(1,-1)">${ground}${demoSVG(d, eqKey, st.p, st.e, DEMO_OPTS, m, trail)}</g>`;
    const lab = (d.o.labels || d.pat.labels)[st.phase] || '';
    if (phaseEl && phaseEl.textContent !== lab) phaseEl.textContent = lab;
    if (scrub && scrubP == null) scrub.value = Math.round(st.p * 1000);
  };
  const frame = now => {
    if (!svg.isConnected) return stop();
    const dt = last == null ? 0 : Math.min(0.1, (now - last) / 1000);
    last = now;
    if (DEMO_OPTS.playing && scrubP == null) t += dt * (DEMO_OPTS.slow ? 0.35 : 1);
    const st = scrubP != null ? { p: scrubP, phase: scrubP > 0.5 ? 2 : 0, e: 0.15 + 0.75 * (tl.hardEnd === 1 ? scrubP : 1 - scrubP) } : demoAt(tl, t);
    draw(st);
    raf = requestAnimationFrame(frame);
  };
  const stop = () => { cancelAnimationFrame(raf); };
  _demoRun = { stop };
  const btn = (id, key, label) => {
    const b = $(id, bg); if (!b) return;
    b.onclick = () => {
      DEMO_OPTS[key] = !DEMO_OPTS[key];
      b.classList.toggle('on', DEMO_OPTS[key]); b.setAttribute('aria-pressed', DEMO_OPTS[key]);
      if (key === 'path') trail = [];
      if (label) label(b);
    };
  };
  btn('#dmSlow', 'slow'); btn('#dmMus', 'muscles'); btn('#dmPath', 'path');
  const play = $('#dmPlay', bg);
  if (play) play.onclick = () => {
    DEMO_OPTS.playing = !DEMO_OPTS.playing;
    if (DEMO_OPTS.playing) scrubP = null;
    play.textContent = DEMO_OPTS.playing ? '❚❚' : '▶';
    play.setAttribute('aria-label', DEMO_OPTS.playing ? 'Pause' : 'Play');
  };
  if (scrub) scrub.oninput = () => {
    scrubP = scrub.value / 1000; trail = [];
    if (DEMO_OPTS.playing) { DEMO_OPTS.playing = false; if (play) { play.textContent = '▶'; play.setAttribute('aria-label', 'Play'); } }
  };
  if (!DEMO_OPTS.playing && scrubP == null) scrubP = 0.5;
  raf = requestAnimationFrame(frame);
}

