export function sidesText(s) {
  const sd = s && s.sides;
  if (!sd) return '';
  const diff = sd.L.w !== sd.R.w;
  const one = k => `${k} ${diff ? nice(dw(sd[k].w)) + '×' : ''}${sd[k].r == null ? '—' : sd[k].r}`;
  return ` (${one('L')} · ${one('R')})`;
}

/* ---------------- lift classification: priority lifts and main lifts (moved in, E17) ---------------- */
export function priorityKeys() { return (S.settings.priority || []).map(p => p && p.leaf ? leafKey(p.leaf) : p); }
export function shortLift(n) {
  const s = n.toLowerCase();
  if (s.includes('squat')) return 'Squat';
  if (s.includes('bench')) return 'Bench';
  if (s.includes('dead')) return 'Deadlift';
  return n;
}
/* ---------------- rest timer ----------------
   Starts itself when a set is ticked. Main lifts rest longer than accessories;
   an exercise can carry its own default (its ⋯ menu), and ±15 s during a
   session sticks for that exercise for the rest of the session.

   The state is an end timestamp on the live session, so it survives the phone
   locking, the app being backgrounded and even a reload: whatever the clock
   says on return is right. The loop only paints and fires the alerts — it is
   never the clock. */
const HEAVY_BARS = ['barbell', 'trap_bar', 'safety_squat_bar'];
/* No compound flag in the catalogue, so: a priority lift, or a heavy-bar
   movement that is either multi-muscle or a squat/pull/press pattern. A
   barbell curl is an accessory; a barbell row isn't. Holds rest like
   accessories. */
export function isMainLift(e) {
  if (!e || !e.leaf || !inRepsPool(e)) return false;
  if (priorityKeys().includes(leafKey(e.leaf))) return true;
  const m = movementById(e.leaf.movement);
  return !!m && HEAVY_BARS.includes(e.leaf.equipment)
    && ((m.primary || []).length >= 2 || ['legs', 'back', 'chest'].includes(m.category));
}
